recipes.code:
{
  "inputs": [
    {
      "id": "slack-token",
      "type": "promptString",
      "description": "Slack xoxc- token from browser session",
      "password": true
    },
    {
      "id": "slack-cookie",
      "type": "promptString",
      "description": "Slack xoxd- cookie from browser session",
      "password": true
    }
  ],
  "servers": {
    "slack": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@jtalk22/slack-mcp@4.6.0"
      ],
      "env": {
        "SLACK_TOKEN": "${input:slack-token}",
        "SLACK_COOKIE": "${input:slack-cookie}"
      }
    }
  }
}
